sys_script_include.script:
var UpdatePriorityConfigurationRule = Class.create();
UpdatePriorityConfigurationRule.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    UpdateConfigurationRule: function() {
        var clientObj = {};
        var priorityRule = this.getParameter('sysparm_checklist');

        var gr = new GlideRecord('x_hsb11_hsbc_mss_o_task_priority_config');
        gr.addQuery('sys_id', priorityRule);
        gr.query();
        if (gr.next()) {
            clientObj.enabled = gr.getDisplayValue('enabled');
			clientObj.u_target_app = gr.getDisplayValue('u_target_app');
			clientObj.field_from_task = gr.getDisplayValue('field_from_task');
			clientObj.entity = gr.getDisplayValue('entity');
			clientObj.from_table = gr.getDisplayValue('from_table');
			clientObj.expected_value = gr.getDisplayValue('expected_value');
			clientObj.expected_display = gr.getDisplayValue('expected_display');
			clientObj.points = gr.getDisplayValue('points');
			clientObj.u_fff = gr.getDisplayValue('u_fff');
			clientObj.table = gr.getDisplayValue('table');
			clientObj.conditions = new global.GlobalQueryUtil().getReadableQuery(clientObj.table, gr.getDisplayValue('conditions'));


        }
        return JSON.stringify(clientObj);
    },

    type: 'UpdatePriorityConfigurationRule'
});
